from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="Extensible CLI Calculator")

    # Define valid operations
    ops = [
        'add', 'subtract', 'multiply', 'divide', 
        'power', 'modulo', 'evaluate', 
        'memory_store', 'memory_recall', 'memory_clear', 
        'get_history', 'clear_history'
    ]

    parser.add_argument("--op", choices=ops, required=True, help="Operation to perform")
    parser.add_argument("a", type=float, nargs='?', help="First operand or value for store/evaluate")
    parser.add_argument("b", type=float, nargs='?', help="Second operand")
    parser.add_argument("--expr", type=str, help="Mathematical expression for evaluate")

    args = parser.parse_args()
    calc = Calculator()

    try:
        # Handle operations based on signatures
        if args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            if args.a is None or args.b is None:
                print("Error: This operation requires two arguments (a and b).")
                return
            func = getattr(calc, args.op)
            result = func(args.a, args.b)
            print(f"Result: {result}")

        elif args.op == 'evaluate':
            if args.expr is None:
                print("Error: 'evaluate' requires --expr argument.")
                return
            result = calc.evaluate(args.expr)
            print(f"Result: {result}")

        elif args.op == 'memory_store':
            if args.a is None:
                print("Error: 'memory_store' requires a value.")
                return
            calc.memory_store(args.a)
            print(f"Stored {args.a} in memory.")

        elif args.op == 'memory_recall':
            print(f"Memory: {calc.memory_recall()}")

        elif args.op == 'memory_clear':
            calc.memory_clear()
            print("Memory cleared.")

        elif args.op == 'get_history':
            print(f"History: {calc.get_history()}")

        elif args.op == 'clear_history':
            calc.clear_history()
            print("History cleared.")

    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

