import ast
import operator
from typing import List, Dict, Any, Union, Optional

class Calculator:
    def __init__(self):
        """Initializes the calculator with an empty history and no memory."""
        self._history: List[Dict[str, Any]] = []
        self._memory: Optional[float] = None

    def _record(self, op: str, a: float, b: float, res: float) -> None:
        """Internal helper to log operations."""
        self._history.append({"op": op, "a": float(a), "b": float(b), "result": float(res)})

    def add(self, a: float, b: float) -> float:
        """Adds two numbers and records the operation."""
        res = float(a + b)
        self._record("add", a, b, res)
        return res

    def subtract(self, a: float, b: float) -> float:
        """Subtracts two numbers and records the operation."""
        res = float(a - b)
        self._record("subtract", a, b, res)
        return res

    def multiply(self, a: float, b: float) -> float:
        """Multiplies two numbers and records the operation."""
        res = float(a * b)
        self._record("multiply", a, b, res)
        return res

    def divide(self, a: float, b: float) -> float:
        """Divides two numbers and records the operation."""
        if b == 0:
            raise ValueError("Division by zero is not allowed.")
        res = float(a / b)
        self._record("divide", a, b, res)
        return res

    def get_history(self) -> List[Dict[str, Any]]:
        """Returns a list of shallow copies of the operation history."""
        return [entry.copy() for entry in self._history]

    def clear_history(self) -> None:
        """Clears all stored history."""
        self._history = []

    def evaluate(self, expression: str) -> float:
        """
        Parses and evaluates a string expression respecting precedence.
        """
        def _eval(node: ast.AST) -> float:
            if isinstance(node, ast.Constant):
                return float(node.value)
            if isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                ops = {
                    ast.Add: operator.add,
                    ast.Sub: operator.sub,
                    ast.Mult: operator.mul,
                    ast.Div: operator.truediv,
                    ast.Pow: operator.pow,
                    ast.Mod: operator.mod,
                }
                op_type = type(node.op)
                if op_type not in ops:
                    raise TypeError(f"Unsupported operator: {op_type.__name__}")

                if op_type in (ast.Div, ast.Mod) and right == 0:
                    raise ValueError("Division/Modulo by zero is not allowed.")

                return float(ops[op_type](left, right))
            if isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                if isinstance(node.op, ast.USub): return -operand
                if isinstance(node.op, ast.UAdd): return operand
            raise TypeError(f"Unsupported expression component: {type(node).__name__}")

        try:
            tree = ast.parse(expression, mode='eval')
            result = float(_eval(tree.body))
            self._record("evaluate", 0.0, 0.0, result)
            return result
        except (SyntaxError, TypeError, ZeroDivisionError) as e:
            raise ValueError(f"Invalid expression: {e}")

    def power(self, base: float, exponent: float) -> float:
        """Calculates base raised to the power of exponent."""
        try:
            res = float(pow(base, exponent))
            self._record("power", base, exponent, res)
            return res
        except (ValueError, ZeroDivisionError) as e:
            raise ValueError(f"Math domain error: {e}")

    def modulo(self, a: float, b: float) -> float:
        """Calculates the remainder of a divided by b."""
        if b == 0:
            raise ValueError("Modulo by zero is not allowed.")
        res = float(a % b)
        self._record("modulo", a, b, res)
        return res

    def memory_store(self, value: float) -> None:
        """Stores a value in memory."""
        val = float(value)
        self._memory = val
        self._record("memory_store", val, 0.0, val)

    def memory_recall(self) -> float:
        """Returns the value currently stored in memory."""
        if self._memory is None:
            raise ValueError("Memory is empty.")
        val = self._memory
        self._record("memory_recall", 0.0, 0.0, val)
        return val

    def memory_clear(self) -> None:
        """Resets memory to None."""
        self._memory = None
        self._record("memory_clear", 0.0, 0.0, 0.0)

